 a,b=cols; z=p[(p[a]>={'heat':78.625,'strength':7.235,'water':79.8}[a])&(p[b]>={'heat':78.625,'strength':7.235,'water':79.8}[b])]; print(cols,z[['project','prototype_id',*cols]].to_string(index=False))